// Get the date provided by the AI Agent
const inputDate = $input.item.json.date;

// Convert it to a JavaScript Date object
const date = new Date(inputDate);

// List of weekdays
const weekdays = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday"
];

// Return the weekday
return {
  dayOfWeek: weekdays[date.getDay()]
};
